// Generated by tools/build_admin_assets.mjs; not served without authentication.
export const adminAssets = {"/admin/index.html":{"body":"<!doctype html>\r\n<html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>KANAPET 内部素材管理</title><link rel=\"stylesheet\" href=\"/admin/admin.css\"></head>\r\n<body><header><a href=\"/\">KANA<span>PET</span></a><span>内部素材管理</span><button type=\"button\" id=\"logout\" hidden>退出</button></header>\r\n<main><p id=\"status\" role=\"status\" aria-live=\"polite\"></p>\r\n<section id=\"login-panel\" class=\"panel\" hidden><h1 id=\"login-title\">内部人员登录</h1><p id=\"login-description\">使用内部账号管理产品照片和视频。</p><form id=\"login-form\"><label>内部邮箱<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>密码<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"128\"></label><button type=\"submit\" id=\"login-submit\" class=\"primary\">登录</button></form></section>\r\n<section id=\"workspace\" hidden><div class=\"heading\"><div><h1>产品素材</h1><p>拍摄、上传、整理，再发布。</p></div><small id=\"account\"></small></div>\r\n<label>查找产品<input id=\"search\" type=\"search\" placeholder=\"搜索型号或产品名称，例如 650\"></label>\r\n<label>选择产品型号<select id=\"product-select\"><option value=\"\">请选择产品</option></select></label>\r\n<section id=\"editor\" hidden><div class=\"product-heading\"><h2 id=\"product-title\"></h2><span id=\"publish-state\"></span></div>\r\n<label>照片用途<select id=\"image-profile\"><option value=\"detail\">场景 / 细节照片：保留原比例</option><option value=\"main\">白底产品主图：正方形、82%内容占比</option></select></label><p class=\"note\">照片自动纠正拍摄方向、压缩至500KB以内，最长边不超过1600像素，不放大小图。主图模式仅整理白色/透明边缘并留白，不自动抠图；拍摄场景请选择场景模式。上传后请预览，再发布。</p><div class=\"upload-actions\"><label class=\"button primary\" role=\"button\" tabindex=\"0\">选择照片 / 视频批量上传<input type=\"file\" id=\"files\" accept=\"image/*,video/mp4,video/webm,video/quicktime\" multiple hidden></label><label class=\"button\" role=\"button\" tabindex=\"0\">拍照片<input type=\"file\" id=\"camera-photo\" accept=\"image/*\" capture=\"environment\" hidden></label><label class=\"button\" role=\"button\" tabindex=\"0\">录视频<input type=\"file\" id=\"camera-video\" accept=\"video/*\" capture=\"environment\" hidden></label></div>\r\n<p class=\"note\" id=\"upload-limits\">照片支持 JPG、PNG、WebP（自动处理到500KB以内）；视频支持 MP4、WebM、MOV（每段最多100MB）。MOV 的播放取决于浏览器，建议使用 MP4。</p>\r\n<progress id=\"progress\" value=\"0\" max=\"100\" hidden></progress><p id=\"upload-status\" role=\"status\"></p>\r\n<details><summary>添加 Facebook / YouTube 视频链接</summary><form id=\"link-form\"><label>视频原始链接<input id=\"video-url\" type=\"url\" placeholder=\"https://www.facebook.com/reel/...\" required></label><label>视频比例<select id=\"video-ratio\"><option value=\"9 / 16\">竖屏 9:16</option><option value=\"16 / 9\">横屏 16:9</option><option value=\"1 / 1\">正方形 1:1</option><option value=\"4 / 3\">横屏 4:3</option></select></label><button type=\"submit\">加入草稿</button></form></details>\r\n<p class=\"note\">第一项为默认主图。使用上移、下移调整顺序；视频可选择已有照片作为封面。删除先从草稿移除，发布后才从展示中移除。</p>\r\n<div id=\"media-list\"></div><div id=\"empty\" hidden>还没有素材，请先上传产品照片。</div>\r\n<div class=\"publish-bar\"><button type=\"button\" id=\"save\">保存草稿</button><a id=\"preview\" class=\"button\" target=\"_blank\" rel=\"noopener\">预览草稿</a><button type=\"button\" id=\"publish\" class=\"primary\">发布到本地预览</button></div>\r\n<p class=\"note\" id=\"publish-note\">本地发布只更新这台电脑及同 Wi-Fi 手机看到的预览，不会改变正式官网。云端上线将单独接入。</p>\r\n</section>\r\n<details class=\"panel\" id=\"internal-users\"><summary>添加内部账号</summary><form id=\"user-form\"><label>内部邮箱<input id=\"user-email\" type=\"email\" required autocomplete=\"off\"></label><label>初始密码（至少12位）<input id=\"user-password\" type=\"password\" required minlength=\"12\" maxlength=\"128\" autocomplete=\"new-password\"></label><button type=\"submit\">创建内部账号</button></form></details>\r\n</section></main><script src=\"/admin/image-processing.js\"></script><script src=\"/admin/admin.js\"></script></body></html>","type":"text/html; charset=utf-8"},"/admin/admin.css":{"body":":root{font-family:Arial,\"Microsoft YaHei\",sans-serif;color:#203d3b;background:#f4f7f6;font-size:16px}*{box-sizing:border-box}body{margin:0}header{padding:18px 24px;background:#fff;border-bottom:1px solid #dce7e4;display:flex;align-items:center;gap:18px}header a{text-decoration:none;font-weight:800;color:#204d45;font-size:22px}header a span{color:#e77832}header button{margin-left:auto}main{max-width:960px;padding:24px;margin:auto}h1{font-size:28px;margin:0 0 12px}h2{font-size:21px;margin:0}p{line-height:1.6}label{display:block;font-weight:600;margin:16px 0}input,select{width:100%;padding:13px;border:1px solid #b5c9c1;border-radius:8px;margin-top:8px;font:inherit;background:white;color:inherit}button,.button{min-height:44px;padding:12px 16px;border:1px solid #9bb7ae;border-radius:8px;background:#fff;color:#204d45;font:inherit;font-weight:600;cursor:pointer;text-decoration:none;text-align:center;display:inline-flex;align-items:center;justify-content:center}button:disabled{opacity:.5;cursor:wait}.primary{background:#204d45;color:#fff;border-color:#204d45}.panel{background:#fff;border:1px solid #dce7e4;border-radius:12px;padding:24px;margin-bottom:24px}#login-panel{max-width:440px;margin:30px auto}.heading,.product-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.heading p{margin:0;color:#607873}.upload-actions{display:flex;gap:10px;flex-wrap:wrap}.upload-actions label{margin:18px 0 0}.note{color:#607873;font-size:13px}.media-card{display:grid;grid-template-columns:160px 1fr;gap:18px;padding:18px;margin:16px 0;border:1px solid #dce7e4;background:white;border-radius:12px}.media-preview{background:#eef3f1;border-radius:8px;overflow:hidden;min-height:120px;display:flex;align-items:center;justify-content:center}.media-preview img,.media-preview video{width:100%;max-height:180px;object-fit:contain}.media-meta label{font-size:14px;margin:0 0 10px}.media-actions{display:flex;gap:8px;flex-wrap:wrap}.media-actions button{padding:8px 12px;font-size:14px}.danger{color:#a32a25;border-color:#dfada9}.publish-bar{position:sticky;bottom:0;padding:16px 0;background:#f4f7f6;display:flex;gap:10px;flex-wrap:wrap;border-top:1px solid #dce7e4}.publish-bar .primary{margin-left:auto}#status:empty,#upload-status:empty{display:none}#status{background:#fff4da;padding:12px;border-radius:8px}progress{width:100%;margin-top:18px}details{margin:20px 0}summary{cursor:pointer;font-weight:600;min-height:44px;padding:12px 0}small,#publish-state{font-size:12px;color:#607873}[hidden]{display:none!important}:focus-visible{outline:3px solid #e77832;outline-offset:3px}@media(max-width:600px){header{padding:14px;gap:10px;font-size:12px}header a{font-size:19px}main{padding:16px}.heading{display:block}.media-card{grid-template-columns:90px 1fr;gap:12px;padding:12px}.media-preview{min-height:100px}.media-preview img,.media-preview video{max-height:150px}.product-heading{display:block}#publish-state{display:block;margin-top:6px}.publish-bar .primary{margin-left:0;flex:1}.upload-actions .button{flex:1}.heading small{display:block;margin-top:8px}}\r\n.confirm-dialog{max-width:420px;width:calc(100% - 32px);border:1px solid #b5c9c1;border-radius:12px;padding:24px;color:#203d3b}.confirm-dialog::backdrop{background:rgba(20,40,35,.45)}\r\n","type":"text/css; charset=utf-8"},"/admin/admin.js":{"body":"function confirmAction(message){return new Promise(resolve=>{\r\n const dialog=document.createElement('dialog');dialog.className='confirm-dialog';\r\n const text=document.createElement('p');text.textContent=message;\r\n const actions=document.createElement('div');actions.className='media-actions';\r\n const cancel=document.createElement('button');cancel.type='button';cancel.textContent='取消';\r\n const accept=document.createElement('button');accept.type='button';accept.textContent='确认';accept.className='primary';\r\n function done(value){dialog.close();dialog.remove();resolve(value);}\r\n cancel.addEventListener('click',()=>done(false));accept.addEventListener('click',()=>done(true));\r\n dialog.addEventListener('cancel',event=>{event.preventDefault();done(false);});\r\n actions.append(cancel,accept);dialog.append(text,actions);document.body.appendChild(dialog);dialog.showModal();\r\n});}\r\nconst $=id=>document.getElementById(id);\r\nlet csrf='',setup=false,cloud=false,products=[],current='',draft=null,busy=false,dirty=false;\r\nfunction status(message){$('status').textContent=message;}\r\nasync function api(path,{method='GET',data,headers={},body}={}){\r\n const response=await fetch(path,{method,headers:{...(data?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{}),...headers},body:data?JSON.stringify(data):body});\r\n const result=await response.json();if(!response.ok){if(response.status===401)status('登录已过期，请重新登录');throw new Error(result.error||'操作失败');}return result;\r\n}\r\nfunction setBusy(value){busy=value;document.querySelectorAll('#workspace button,#workspace select,#workspace input').forEach(e=>e.disabled=value);$('progress').hidden=!value;}\r\nfunction markDirty(){dirty=true;$('publish-state').textContent='有未保存的修改';}\r\nasync function save(){const result=await api(`/api/admin/products/${current}`,{method:'PUT',headers:{'If-Match':String(draft.revision)},data:{items:draft.items}});draft=result.draft;dirty=false;$('publish-state').textContent='草稿已保存';return result;}\r\nfunction render(){\r\n const list=$('media-list');list.replaceChildren();$('empty').hidden=Boolean(draft.items.length);\r\n draft.items.forEach((item,index)=>{\r\n  const card=document.createElement('article');card.className='media-card';\r\n  const media=document.createElement('div');media.className='media-preview';\r\n  if(item.type==='image'){const img=document.createElement('img');img.src=item.src;img.alt=item.title||'产品照片';img.loading='lazy';media.appendChild(img);}\r\n  else if(item.src.startsWith('/media-assets/')){const video=document.createElement('video');video.src=item.src;video.controls=true;video.playsInline=true;video.preload='metadata';if(item.poster)video.poster=item.poster;media.appendChild(video);}\r\n  else{media.textContent='▶ 外部视频';}\r\n  const meta=document.createElement('div');meta.className='media-meta';\r\n  const label=document.createElement('label');label.textContent=`${index+1}. ${item.type==='image'?'照片':'视频'}${index===0?' · 默认展示':''}`;\r\n  const title=document.createElement('input');title.value=item.title||'';title.maxLength=120;title.setAttribute('aria-label','素材描述');title.addEventListener('input',()=>{item.title=title.value;markDirty();});label.appendChild(title);meta.appendChild(label);if(item.fileName){const info=document.createElement('small');info.textContent=item.fileName;meta.appendChild(info);}\r\n  if(item.type==='video'){\r\n   const posterLabel=document.createElement('label');posterLabel.textContent='视频封面';const select=document.createElement('select');select.appendChild(new Option('不设置封面',''));\r\n   draft.items.filter(i=>i.type==='image').forEach(i=>select.appendChild(new Option(i.title||'产品照片',i.src)));select.value=item.poster||'';select.addEventListener('change',()=>{item.poster=select.value;markDirty();});posterLabel.appendChild(select);meta.appendChild(posterLabel);\r\n  }\r\n  const actions=document.createElement('div');actions.className='media-actions';\r\n  for(const [text,move]of [['上移',-1],['下移',1]]){const button=document.createElement('button');button.textContent=text;button.disabled=index+move<0||index+move>=draft.items.length;button.addEventListener('click',()=>{[draft.items[index],draft.items[index+move]]=[draft.items[index+move],draft.items[index]];markDirty();render();});actions.appendChild(button);}\r\n  const remove=document.createElement('button');remove.textContent='删除';remove.className='danger';remove.addEventListener('click',async()=>{if(!await confirmAction('从草稿移除此素材？保存并发布后才会从产品展示中移除。'))return;draft.items.splice(index,1);for(const i of draft.items)if(i.poster===item.src)delete i.poster;markDirty();render();});actions.appendChild(remove);meta.appendChild(actions);card.append(media,meta);list.appendChild(card);\r\n });\r\n}\r\nasync function loadProduct(slug){const result=await api(`/api/admin/products/${slug}`);current=slug;draft=result.draft;dirty=false;$('editor').hidden=false;$('product-title').textContent=products.find(p=>p.slug===slug).name;$('publish-state').textContent=result.published?(cloud?'已有官网发布版本':'已有本地发布版本'):'当前为官网原有素材';$('preview').href=`/product/${slug}.html?media-preview=draft`;render();}\r\nfunction options(){const search=$('search').value.toLowerCase();const select=$('product-select');select.replaceChildren(new Option('请选择产品',''));products.filter(p=>(p.name+' '+p.slug).toLowerCase().includes(search)).forEach(p=>select.appendChild(new Option(`${p.name} · ${p.slug}`,p.slug)));select.value=current;}\r\nasync function workspace(){const result=await api('/api/admin/products');products=result.products;$('login-panel').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;options();}\r\n$('login-form').addEventListener('submit',async event=>{event.preventDefault();try{$('login-submit').disabled=true;const data={email:$('email').value,password:$('password').value};if(setup)await api('/api/admin/setup',{method:'POST',data});const result=await api('/api/admin/login',{method:'POST',data});csrf=result.csrf;$('account').textContent=result.email;$('password').value='';setup=false;status('');await workspace();}catch(error){status(error.message);}finally{$('login-submit').disabled=false;}});\r\n$('search').addEventListener('input',options);\r\n$('product-select').addEventListener('change',async()=>{const slug=$('product-select').value;if(!slug)return;if(dirty&&!await confirmAction('有未保存的修改，是否放弃并切换产品？')){$('product-select').value=current;return;}try{await loadProduct(slug);status('');}catch(error){status(error.message);}});\r\nasync function metadata(file){const url=URL.createObjectURL(file);try{return await new Promise(resolve=>{const video=file.type.startsWith('video/');const element=document.createElement(video?'video':'img');const timer=setTimeout(()=>resolve(null),8000);const done=()=>{clearTimeout(timer);const w=video?element.videoWidth:element.naturalWidth,h=video?element.videoHeight:element.naturalHeight;resolve(w&&h?`${w} / ${h}`:null);};element.addEventListener(video?'loadedmetadata':'load',done,{once:true});element.addEventListener('error',()=>{clearTimeout(timer);resolve(null);},{once:true});element.src=url;});}finally{URL.revokeObjectURL(url);}}\r\nfunction upload(file){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',`/api/admin/products/${current}/upload?name=${encodeURIComponent(file.name)}`);xhr.setRequestHeader('Content-Type',file.type||'application/octet-stream');xhr.setRequestHeader('X-CSRF-Token',csrf);xhr.setRequestHeader('If-Match',String(draft.revision));xhr.upload.onprogress=event=>{if(event.lengthComputable)$('progress').value=100*event.loaded/event.total;};xhr.onload=()=>{let result;try{result=JSON.parse(xhr.responseText);}catch{return reject(new Error('上传服务异常'));}if(xhr.status<200||xhr.status>=300)return reject(new Error(result.error||'上传失败'));resolve(result);};xhr.timeout=180000;xhr.ontimeout=()=>reject(new Error('上传超时，请检查网络后重试'));xhr.onerror=()=>reject(new Error(cloud?'网络中断，请检查网络后重试':'网络中断，请检查手机与电脑是否在同一 Wi-Fi'));xhr.send(file);});}\r\nfor(const id of ['files','camera-photo','camera-video'])$(id).addEventListener('change',async event=>{\r\n const files=[...event.target.files];if(!files.length||!current)return;setBusy(true);let count=0;const errors=[];\r\n try{if(dirty)await save();for(const file of files){$('upload-status').textContent=`正在上传 ${count+1}/${files.length}：${file.name}`;try{const prepared=await KanapetImages.prepare(file,$('image-profile').value);const ratio=prepared.width?`${prepared.width} / ${prepared.height}`:await metadata(file);const max=cloud?40:100;if(prepared.file.size>max*1024*1024)throw new Error(`视频最多${max}MB，请压缩后上传`);$('upload-status').textContent=`正在上传 ${count+1}/${files.length}：${file.name}${prepared.width?` → ${prepared.width}×${prepared.height}，${Math.ceil(prepared.file.size/1024)}KB`:''}`;const result=await upload(prepared.file);draft=result.draft;const item=draft.items.at(-1);if(ratio)item.aspectRatio=ratio;if(prepared.profile==='main'){draft.items.pop();draft.items.unshift(item);}markDirty();await save();count++;}catch(error){errors.push(`${file.name}：${error.message}`);}}render();status(errors.length?errors.join('；'):'上传完成，素材已保存为草稿');$('upload-status').textContent=`已上传 ${count}/${files.length} 项素材`;}catch(error){status(error.message);}finally{event.target.value='';setBusy(false);render();}\r\n});\r\n$('save').addEventListener('click',async()=>{try{setBusy(true);await save();status('草稿已保存');}catch(error){status(error.message);}finally{setBusy(false);render();}});\r\n$('preview').addEventListener('click',event=>{if(dirty){event.preventDefault();status('请先保存草稿，再打开预览');}});\r\n$('publish').addEventListener('click',async()=>{if(!await confirmAction(cloud?'发布到正式官网？访客将看到此产品的最新照片和视频。':'发布到本地预览？手机与电脑可看到更新，正式官网暂不改变。'))return;try{setBusy(true);if(dirty)await save();const published=await api(`/api/admin/products/${current}/publish`,{method:'POST',headers:{'If-Match':String(draft.revision)},data:{}});draft=published.draft;$('publish-state').textContent=cloud?'已发布到正式官网':'已发布到本地预览';status(cloud?'官网发布成功':'本地发布成功');}catch(error){status(error.message);}finally{setBusy(false);render();}});\r\n$('link-form').addEventListener('submit',async event=>{event.preventDefault();if(!draft)return;draft.items.push({id:crypto.randomUUID?crypto.randomUUID():`link-${Date.now()}-${Math.random().toString(36).slice(2)}`,type:'video',src:$('video-url').value,title:'Product video',aspectRatio:$('video-ratio').value});markDirty();render();try{await save();$('video-url').value='';status('视频链接已加入草稿');}catch(error){status(error.message);}});\r\n$('user-form').addEventListener('submit',async event=>{event.preventDefault();try{await api('/api/admin/users',{method:'POST',data:{email:$('user-email').value,password:$('user-password').value}});$('user-password').value='';status('内部账号已创建');}catch(error){status(error.message);}});\r\n$('logout').addEventListener('click',async()=>{try{const result=await api('/api/admin/logout',{method:'POST',data:{}});if(result.logout)location.href=result.logout;else location.reload();}catch(error){status(error.message);}});\r\nwindow.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});\r\n(async()=>{try{const result=await api('/api/admin/session');if(result.authenticated){cloud=Boolean(result.cloud);if(cloud){document.getElementById('upload-limits').textContent='照片自动处理到500KB以内，视频最多40MB。支持 JPG、PNG、WebP；HEIC 能否读取取决于浏览器，不支持时请导出 JPG。';$('publish').textContent='发布到官网';$('publish-note').textContent='上传先保存为内部草稿，点击发布后正式官网同步更新。';$('internal-users').hidden=true;}csrf=result.csrf;$('account').textContent=result.email;await workspace();}else{setup=result.setup;$('login-panel').hidden=false;if(setup){$('login-title').textContent='创建首个内部账号';$('login-description').textContent='首次请在电脑本机创建管理员，之后可在同 Wi-Fi 手机登录。密码至少12位。';$('password').minLength=12;$('password').autocomplete='new-password';$('login-submit').textContent='创建账号并登录';}}}catch(error){status(location.protocol==='https:'?'后台连接失败，请刷新或重新登录：'+error.message:'请先启动本地素材后台服务，再打开此页面。');}})();\r\n// File inputs remain native so mobile browsers can offer camera or library.\r\ndocument.querySelectorAll('.upload-actions label').forEach(label=>label.addEventListener('keydown',event=>{\r\n if(event.key==='Enter'||event.key===' '){event.preventDefault();label.querySelector('input').click();}\r\n}));","type":"text/javascript; charset=utf-8"},"/admin/image-processing.js":{"body":"// Normalize on the uploading device; originals remain in the phone/computer library.\r\n(function () {\r\n const MAX_BYTES=500*1024, MAX_EDGE=1600;\r\n const imageFile=file=>file.type.startsWith('image/')||/\\.(jpe?g|png|webp|heic|heif|avif)$/i.test(file.name);\r\n const encode=(canvas,type,quality)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('图片转换失败')),type,quality));\r\n async function prepare(file,profile='detail') {\r\n  if(!imageFile(file))return {file};\r\n  if(file.size>40*1024*1024)throw new Error('原始照片超过40MB，请先导出较小的照片');\r\n  let source,url;\r\n  try {\r\n   // Browser decoders apply EXIF orientation before drawing; canvas removes GPS/EXIF metadata.\r\n   if(typeof createImageBitmap==='function')try{source=await createImageBitmap(file,{imageOrientation:'from-image'});}catch{}\r\n   if(!source){url=URL.createObjectURL(file);source=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('照片无法读取。HEIC/HEIF 请导出 JPG，或将手机相机设为“兼容性最佳”'));img.src=url;});}\r\n   const sw=source.width||source.naturalWidth,sh=source.height||source.naturalHeight;\r\n   if(!sw||!sh||sw*sh>80000000)throw new Error('照片尺寸过大或无效，请导出普通分辨率');\r\n   const scale=Math.min(1,MAX_EDGE/Math.max(sw,sh));let w=Math.max(1,Math.round(sw*scale)),h=Math.max(1,Math.round(sh*scale));\r\n   let content=document.createElement('canvas');content.width=w;content.height=h;let ctx=content.getContext('2d');ctx.drawImage(source,0,0,w,h);\r\n   let sx=0,sy=0,cw=w,ch=h;\r\n   if(profile==='main'){\r\n    // Trim only white/transparent outer margin. Never guess or remove a photographic background.\r\n    const pixels=ctx.getImageData(0,0,w,h).data;let left=w,top=h,right=-1,bottom=-1;\r\n    for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4;if(pixels[i+3]>16&&(pixels[i]<245||pixels[i+1]<245||pixels[i+2]<245)){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}}\r\n    if(right>=left){sx=left;sy=top;cw=right-left+1;ch=bottom-top+1;}\r\n    const edge=Math.min(MAX_EDGE,Math.ceil(Math.max(cw,ch)/.82));w=edge;h=edge;\r\n   }\r\n   let canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;ctx=canvas.getContext('2d');\r\n   if(profile==='main'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);const factor=w*.82/Math.max(cw,ch),dw=cw*factor,dh=ch*factor;ctx.drawImage(content,sx,sy,cw,ch,(w-dw)/2,(h-dh)/2,dw,dh);}else ctx.drawImage(content,0,0);\r\n   let blob,type='image/webp';\r\n   for(let round=0;round<8;round++){\r\n    for(const quality of [.9,.82,.74,.66,.58]){blob=await encode(canvas,type,quality);if(blob.type!==type){type='image/jpeg';ctx.fillStyle='#fff';ctx.globalCompositeOperation='destination-over';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-over';blob=await encode(canvas,type,quality);}if(blob.size<=MAX_BYTES)break;}\r\n    if(blob.size<=MAX_BYTES)break;\r\n    const smaller=document.createElement('canvas');smaller.width=Math.max(1,Math.round(canvas.width*.85));smaller.height=Math.max(1,Math.round(canvas.height*.85));smaller.getContext('2d').drawImage(canvas,0,0,smaller.width,smaller.height);canvas=smaller;\r\n   }\r\n   if(!blob||blob.size>MAX_BYTES)throw new Error('无法压缩到500KB，请换一张照片');\r\n   const ext=blob.type==='image/webp'?'webp':'jpg';\r\n   return {file:new File([blob],'processed.'+ext,{type:blob.type}),width:canvas.width,height:canvas.height,profile,originalBytes:file.size};\r\n  } finally {source?.close?.();if(url)URL.revokeObjectURL(url);}\r\n }\r\n window.KanapetImages={prepare,MAX_BYTES,MAX_EDGE};\r\n})();\r\n","type":"text/javascript; charset=utf-8"}};
